arguments.command:
cat > /tmp/repro.py <<'EOF'
from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class CommonHeaders(BaseModel):
    user_agent: str

@app.get("/")
async def read_headers(headers: CommonHeaders = Header()):
    return {"headers": headers}

client = TestClient(app)

def test_underscore_header_rejected():
    # By default convert_underscores=True. 
    # It should accept 'user-agent' and map it to 'user_agent'.
    # It should NOT accept 'user_agent' and map it to 'user_agent'.

    # This should work
    response = client.get("/", headers={"user-agent": "test-agent"})
    assert response.status_code == 200
    assert response.json() == {"headers": {"user_agent": "test-agent"}}

    # This should FAIL (return 422) if the fix is applied
    # Currently it probably works (returns 200)
    response = client.get("/", headers={"user_agent": "test-agent"})
    print(f"Response with underscore header: {response.status_code}, {response.json()}")
    assert response.status_code == 422

def test_underscore_header_accepted_when_disabled():
    # Now we test with convert_underscores=False
    @app.get("/disabled")
    async def read_headers_disabled(headers: CommonHeaders = Header(convert_underscores=False)):
        return {"headers": headers}

    response = client.get("/disabled", headers={"user_agent": "test-agent"})
    assert response.status_code == 200
    assert response.json() == {"headers": {"user_agent": "test-agent"}}

if __name__ == "__main__":
    try:
        test_underscore_header_rejected()
        print("test_underscore_header_rejected passed")
    except AssertionError as e:
        print(f"test_underscore_header_rejected failed: {e}")

    try:
        test_underscore_header_accepted_when_disabled()
        print("test_underscore_header_accepted_when_disabled passed")
    except AssertionError as e:
        print(f"test_underscore_header_accepted_when_disabled failed: {e}")
EOF
python3 /tmp/repro.py

observation.content:
{"status": "ok", "stdout": "Response with underscore header: 200, {'headers': {'user_agent': 'test-agent'}}
test_underscore_header_rejected failed: 
test_underscore_header_accepted_when_disabled passed
", "stderr": "", "exit_code": 0}

